import { execSync } from 'child_process';
import fs from 'fs';
const W='';
const FILES={'includes/class-feeding-service.php':'','MU:petshop-feeding-calc-rest.php':''};
const TOKG=process.env.GH_TOKEN, REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const U=process.env.WP_USER||'', P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='-u "'+U+':'+P+'"';
function wj(m,path,body){fs.writeFileSync('/tmp/wb.json', JSON.stringify(body));
  return execSync('curl -sk --max-time 150 '+AUTH+' -X '+m+' -H "Content-Type: application/json" --data-binary @/tmp/wb.json "https://dev.avesa.lt/wp-json/'+path+'"',{maxBuffer:50e6,timeout:170000}).toString();}
function putB64(name,b64){const u='https://api.github.com/repos/'+REPO+'/contents/screenshots/'+name;let s='';
 for(let i=0;i<6;i++){try{const j=JSON.parse(execSync('curl -s -H "Authorization: Bearer '+TOKG+'" "'+u+'?n='+Math.random()+'"',{maxBuffer:50e6}).toString());if(j.sha)s=j.sha;}catch(e){}
  fs.writeFileSync('/tmp/pj.json',JSON.stringify({message:'r',content:b64,...(s?{sha:s}:{})}));
  const c=execSync('curl -s -o /dev/null -w "%{http_code}" -X PUT -H "Authorization: Bearer '+TOKG+'" -d @/tmp/pj.json "'+u+'"',{maxBuffer:50e6}).toString().trim();
  if(c==='200'||c==='201')return c; execSync('sleep 3');}return 'fail';}
const o={marker:'S278'}; let sid=null;
try{
  let mk=null;
  for(let a=0;a<3;a++){ try{ mk=wj('POST','code-snippets/v1/snippets',{name:'S278 '+Date.now(),code:Buffer.from(W,'base64').toString('utf8'),scope:'front-end',active:true,priority:5});
    if(mk && mk.indexOf('"id"')>=0) break; }catch(e){} execSync('sleep 8'); }
  try{sid=JSON.parse(mk).id;}catch(e){o.mk=String(mk).slice(0,120);}
  execSync('sleep 5');
  fs.writeFileSync('/tmp/payload.json', JSON.stringify({files:FILES}));
  for(let a=0;a<3;a++){ try{const r=execSync('curl -sk --max-time 120 -X POST -H "Content-Type: application/json" --data-binary @/tmp/payload.json "https://dev.avesa.lt/?ps_dep218=Dp218x"',{maxBuffer:20e6,timeout:140000}).toString();
    const j=r.slice(r.indexOf('{'),r.lastIndexOf('}')+1); o.write=j; if(j.includes('feeding-service')&&j.includes('feeding-calc-rest')) break; }catch(e){o.write='ERR '+a;} execSync('sleep 5'); }
  if(sid!==null){ try{execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"');}catch(e){} sid=null; }
  // ijungiam veliavele + testuojam VIESAI (be prisijungimo)
  const vphp='<?php add_action("wp_loaded",function(){ if(!isset($_GET["ps_v278"])||$_GET["ps_v278"]!=="V278x") return; $o=array(); '
   +'update_option("petshop_feeding_calc_enabled","1"); update_option("petshop_feeding_calc_kill","0"); '
   +'$o["flag"]=get_option("petshop_feeding_calc_enabled"); $o["kill"]=get_option("petshop_feeding_calc_kill"); '
   +'$o["enabled"]=Petshop_Feeding_Service::calc_enabled(); '
   +'header("Content-Type: application/json"); echo json_encode($o); exit; });';
  let mk2=null;
  for(let a=0;a<3;a++){ try{ mk2=wj('POST','code-snippets/v1/snippets',{name:'V278 '+Date.now(),code:vphp,scope:'front-end',active:true,priority:5});
    if(mk2 && mk2.indexOf('"id"')>=0) break; }catch(e){} execSync('sleep 8'); }
  let sid2=null; try{sid2=JSON.parse(mk2).id;}catch(e){}
  execSync('sleep 5');
  try{ const r=execSync('curl -sk --max-time 60 "https://dev.avesa.lt/?ps_v278=V278x"',{maxBuffer:8e6,timeout:75000}).toString();
    const i=r.indexOf('{'),k=r.lastIndexOf('}'); if(i>=0&&k>i) o.flag=JSON.parse(r.slice(i,k+1)); }catch(e){}
  if(sid2!==null){ try{execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid2+'"');}catch(e){} }
  // TIKRI VIESI kvietimai — BE jokio prisijungimo
  const call=(body)=>{ fs.writeFileSync('/tmp/cb.json', JSON.stringify(body));
    const r=execSync('curl -sk --max-time 45 -X POST -H "Content-Type: application/json" --data-binary @/tmp/cb.json "https://dev.avesa.lt/wp-json/petshop/v1/feeding-calc"',{maxBuffer:8e6,timeout:60000}).toString();
    try{ return JSON.parse(r); }catch(e){ return {raw:r.slice(0,200)}; } };
  const pick=(r)=>({status:r.status,reason:r.reason_codes,norm:(r.norm_min_g??null)+'-'+(r.norm_max_g??null),
    days:(r.days_min??null)+'-'+(r.days_max??null),eur:(r.cost_day_min??null)+'-'+(r.cost_day_max??null),
    rng:(r.weight_range_from_kg??null)+'-'+(r.weight_range_to_kg??null),basis:r.basis??null,
    msg:(r.message_lt||'').slice(0,110)});
  o.tinka   = pick(call({product_id:18620, weight_kg:13, species_code:'dog', activity_code:'moderate'}));
  o.uz_ribu = pick(call({product_id:18620, weight_kg:8,  species_code:'dog'}));
  o.porcija = pick(call({product_id:18620, portion_g:180}));
}catch(e){ o.err=String(e).slice(0,250); }
try{ if(sid!=null) execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"'); }catch(e){}
putB64('s278.json', Buffer.from(JSON.stringify(o)).toString('base64'));
console.log('done');
